const monthly: PackageRenewal = {
  type: "every",
  agreed: {
    cadence: { interval: "month", interval_count: 1 },
    on_exhaustion: { type: "pause" },
    unpaid_order: { type: "retain_debt" },
  },
  timing: {
    retry_offsets_seconds: [86400],
    recovery_window_seconds: 604800,
    reminder: { type: "none" },
  },
};
const yearly: PackageStay = { type: "at_least", length: { interval: "year", interval_count: 1 }, then: { type: "renew_once" } };
const rental: PackageAutomaticItemType = { type: "rent_product", variant_id: "variant", quantity: 1, tax_category_id: "tax", allocation_weight: 0 };
const terms: StorefrontPackageItemTerms = { id: "item", type: { type: "rent_product", variant_id: "variant", quantity: 1, tax_category_id: "tax" } };
const renewing: PackageMemberRenewal = {
  type: "every",
  next_occurrence_index: 2,
  payment_method: { type: "card", payment_method_id: "method", by: { type: "customer", customer_id: "customer", customer_session_id: "session" }, accepted_at: epochMilliseconds(1) },
  renewal_end: { type: "never" },
};
void [monthly, yearly, rental, terms, renewing];
